<?php require __DIR__.'/app/bootstrap.php';header('Content-Type: application/xml; charset=utf-8');$base=APP_URL?:((!empty($_SERVER['HTTPS'])?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost'));echo '<?xml version="1.0" encoding="UTF-8"?>';?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9"><url><loc><?=e($base.'/')?></loc></url><?php foreach(db()->query('SELECT slug,updated_at FROM songs WHERE published=1') as $s):?><url><loc><?=e($base.'/song/'.$s['slug'])?></loc><lastmod><?=date('c',strtotime($s['updated_at']))?></lastmod></url><?php endforeach?></urlset>